from pathlib import Path
from docx import Document
from docx.shared import Pt, Mm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

root=Path('docs/report')
source=root/'Ульянкин_ВИ_ИКБО-30-24_Учебная_практика_этап4_ООП_итог.docx'
output=root/'Ульянкин_ВИ_ИКБО-30-24_Учебная_практика_этап4_организация.docx'
doc=Document(source)
anchor=next(p for p in doc.paragraphs if p.text.strip()=='СПИСОК ЛИТЕРАТУРЫ')

def paragraph(text,style=None):
    p=anchor.insert_paragraph_before(style=style);r=p.add_run(text)
    r.font.name='Times New Roman';r.font.size=Pt(14)
    fonts=r._element.get_or_add_rPr().get_or_add_rFonts()
    for a in ('ascii','hAnsi','cs','eastAsia'):fonts.set(qn('w:'+a),'Times New Roman')
    if not style:
        p.paragraph_format.first_line_indent=Mm(12.5);p.paragraph_format.line_spacing=1.5;p.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
    return p

def table(caption,headers,rows):
    cap=paragraph(caption,'Подпись таблиц ГОСТ');cap.paragraph_format.keep_with_next=True
    t=doc.add_table(rows=1,cols=len(headers));t.style='Table Grid'
    for i,data in enumerate([headers]+rows):
        cells=t.rows[0].cells if i==0 else t.add_row().cells
        for cell,value in zip(cells,data):
            p=cell.paragraphs[0];p.alignment=WD_ALIGN_PARAGRAPH.LEFT;p.paragraph_format.first_line_indent=Pt(0);p.paragraph_format.line_spacing=1;p.paragraph_format.space_after=Pt(0)
            r=p.add_run(value);r.bold=(i==0);r.font.name='Times New Roman';r.font.size=Pt(10)
        t.rows[-1]._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
    t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
    anchor._p.addprevious(t._tbl)
    return cap

p=paragraph('ГЛАВА 4. ОРГАНИЗАЦИОННОЕ ОБЕСПЕЧЕНИЕ ПРОЕКТА И ПРОФЕССИОНАЛЬНОЕ РАЗВИТИЕ','Heading 1');p.paragraph_format.page_break_before=True
paragraph('4.1. СОСТАВ КОМАНДЫ И РАСПРЕДЕЛЕНИЕ ОТВЕТСТВЕННОСТИ','Heading 2')
paragraph('Для развития прототипа в рабочую систему одной VR-арены рассмотрена предполагаемая проектная команда. Это организационная модель проекта, а не перечень фактических участников практики. Состав определяется необходимостью согласовать правила бронирования с работой площадки, развить доменную логику и физическую модель данных, обеспечить проверку и развёртывание. Предлагаемое распределение представлено в таблице 18.')
roles=[
('Аналитик и координатор','Уточняет требования администратора, ведёт приоритеты, согласует сценарии отмены, переноса и приёмки.','BPMN, требования и критерии приёмки, понимание процесса сеансового обслуживания.','Работает с представителем арены, разработчиками и тестировщиком; на небольшом проекте может совмещать координацию и анализ.'),
('Java-разработчик серверной части','Развивает доменную логику, проверку брони, историю, тесты и в дальнейшем физическую модель данных и API.','Java, ООП, SQL и моделирование данных, Git, тестирование.','Согласует контракты с разработчиком интерфейса и проверки с тестировщиком; отвечает за код главы 3.'),
('Разработчик интерфейса','На следующем этапе создаёт экран администратора для просмотра расписания и выполнения операций.','Проектирование интерфейсов, клиентская разработка, работа с API.','Согласует сценарии с администратором и контракты с серверным разработчиком; до появления интерфейса роль может привлекаться частично.'),
('Тестировщик','Разрабатывает сценарии проверки конфликтов времени, неявки, возврата комплектов и пограничных условий.','Тест-дизайн, анализ граничных случаев, воспроизведение дефектов, работа с результатами тестов.','Получает критерии приёмки от аналитика и проверяет изменения разработчиков; часть проверок может выполнять разработчик при независимом просмотре результатов.'),
('Инженер развёртывания','При переходе к работающей системе настраивает окружение, сборку и резервное копирование данных.','Сборка Java, администрирование среды, основы эксплуатации и резервного копирования.','Взаимодействует с серверным разработчиком; для небольшого прототипа функции можно совмещать или привлекать специалиста по мере необходимости.'),
('Представитель VR-арены','Проверяет реалистичность сценариев приёма, инструктажа, выдачи комплектов и подготовки площадки.','Практическое знание работы администратора и оборудования точки.','Согласует требования и демонстрации с аналитиком и тестировщиком; не обязан входить в штат команды разработки.')]
table('Таблица 18 — Предполагаемые роли и взаимодействие команды',['Роль','Ответственность','Компетенции','Взаимодействие и совмещение'],roles)
paragraph('Для одной площадки выделять отдельного специалиста на каждую функцию постоянно не требуется. Аналитик может координировать работу, а разработчик — поддерживать среду на ранней стадии; при этом критерии приёмки и проверка изменений должны оставаться явными. Представитель арены необходим для проверки предметных допущений, поскольку команда разработки не может самостоятельно подтвердить реальные регламенты точки.')
paragraph('4.2. ОРГАНИЗАЦИЯ СОВМЕСТНОЙ РАБОТЫ','Heading 2')
paragraph('Предлагается использовать короткие итерации продолжительностью около двух недель с выбором задач из общего списка. Это адаптация отдельных практик Agile и Scrum к небольшому составу, а не утверждение о проведённых церемониях. На начало итерации команда выбирает ограниченный результат, например сохранение истории брони или проверку конфликтов; в конце демонстрирует его на воспроизводимом сценарии и уточняет следующие задачи. Основные элементы работы представлены в таблице 19.')
practices=[
('Список задач','Аналитик формулирует задачу, приоритет, связь с проблемой проекта и критерии приёмки; команда уточняет оценку и зависимости.','В задаче о переносе указаны проверка слота, сохранение прежних данных при отказе и запись истории при успехе.'),
('Планирование итерации','На планировании выбирается объём, который можно реализовать и проверить в течение итерации; новые срочные задачи согласуются отдельно.','Для следующей контрольной точки выделяются проектирование физической модели данных и проверки её ограничений.'),
('Доска состояния','Задачи последовательно проходят состояния «Запланировано», «В работе», «На проверке» и «Готово»; препятствия отмечаются в карточке.','В одной карточке видны ответственный, изменённые файлы, тесты и результат проверки.'),
('Ветки и просмотр изменений','Для задачи создаётся отдельная Git-ветка; после локальной проверки предлагаются изменения для просмотра другим участником.','В существующем репозитории этап выделен веткой stage4-oop; для командной работы предлагаются небольшие тематические изменения и запрос на слияние.'),
('Демонстрация и ретроспектива','В конце итерации команда показывает результат представителю арены и обсуждает одно-два конкретных улучшения процесса.','Демонстрируются конфликт бронирования, перенос и запись истории; обратная связь отражается в новых задачах.')]
table('Таблица 19 — Предлагаемые практики совместной работы',['Практика','Порядок работы','Применение к проекту'],practices)
paragraph('Критерий готовности задачи (Definition of Done): выполнены её критерии приёмки, изменения согласованы с моделью и связанными схемами, относящиеся к изменению проверки выполнены, результат проверен другим участником, а команды запуска и ограничения актуальны. Для изменений Python используются run_cases.py и unittest; для Java-модуля — Maven и JUnit. Если задача не меняет код, применяются соответствующие ей проверки документа или схем, а не формальный запуск всех тестов.')
paragraph('Такой порядок подходит проекту с небольшим числом ролей: он сохраняет связь между проблемой арены, задачей и проверяемым изменением, не требует постоянного присутствия отдельных владельца продукта и Scrum-мастера и позволяет совмещать функции. Описание является предложением организации работы; фактические результаты взаимного рецензирования рассматриваются отдельно после обмена материалами.')

doc.save(output);Document(output)
